"use client";

import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from "react";
import { Empty, Icon, Logo, Message, Preferences, useUI, type IconName } from "./ui";
import { PublicFooter, PublicHeader } from "./landing";
import { ManagementTools, RubricPanel, ContactInbox, IdentityRequests } from "./management-tools";
import { roleNames } from "@/lib/content";
import { academicPermissions, canOpenPortalView } from "@/lib/portal-access";
import { selectPreview, previewViewer, str, number, type Row, type Dataset } from "@/lib/preview-data";
import { prepareEvidence } from "@/client/evidence";
import type { Role } from "@/contracts/academic";

type View = "overview" | "courses" | "tasks" | "grades" | "calendar" | "notifications" | "profile" | "users" | "structure" | "audit" | "security" | "new-task" | "detail" | "contacts";
type Command = (operation: string, params: Record<string, unknown>) => Promise<unknown>;
const academicResources = ["groups", "subjects", "programs", "periods", "categories", "tasks", "submissions", "submission_versions", "comments", "final_results", "notifications", "calendar_events", "uploads", "content_translations", "rubrics", "grade_history", "enrollments"];
const systemResources = ["profiles", "audit_events", "deletion_requests", "invitation_jobs", "notifications", "uploads"];
const adminResources = ["profiles", "groups", "subjects", "programs", "periods", "categories", "enrollments", "teacher_groups", "identity_requests", "calendar_events", "notifications", "uploads", "content_translations", "contact_inquiries"];
const idempotent = ["publish_task", "submit_work", "review_work", "add_comment", "close_period", "manage_structure"];

export function PreviewChooser() {
  const { t, lang } = useUI();
  return <><PublicHeader /><main id="main" className="role-chooser"><h1>{t("Conoce tu campus.", "Discover your campus.")}</h1><p>{t("Explora cada espacio con una cuenta de ejemplo y sus funciones específicas. La vista previa está separada del acceso institucional y no utiliza credenciales.", "Explore each workspace with a sample account and its specific features. Preview is separate from institutional access and uses no credentials.")}</p><div className="role-options">{(Object.keys(roleNames) as Role[]).map(role => <Link href={`/vista-previa?rol=${role}`} key={role}><div><strong>{roleNames[role][lang]}</strong><p>{t("Explorar el espacio de muestra", "Explore the sample workspace")}</p></div><Icon name="arrow" /></Link>)}</div></main><PublicFooter /></>;
}

export function Portal({ previewRole }: { previewRole?: Role }) {
  const { t, lang, api, user, logout, previewStore, changePreview, previewFiles } = useUI(); const router = useRouter(); const preview = Boolean(previewRole);
  const role = previewRole ?? user?.roles[0]?.role;
  const permissions: readonly string[] = previewRole === "academic_admin" ? academicPermissions : user?.permissions.map(item => item.permission) ?? [];
  const can = (permission: string) => role === "academic_admin" && permissions.includes(permission);
  const viewerId = previewRole ? previewViewer(previewRole).fixture_id : user?.profile.id ?? "";
  const viewerName = previewRole ? str(previewStore.profiles.find(p => p.id === viewerId), "full_name", previewViewer(previewRole).full_name) : user?.profile.full_name ?? "";
  const [data, setData] = useState<Dataset>(() => previewRole ? selectPreview(previewStore, previewRole) : {});
  const dataRef = useRef(data);
  const [dataOwner, setDataOwner] = useState(preview ? viewerId : ""); const loadGeneration = useRef(0);
  const [view, setView] = useState<View>("overview"); const [group, setGroup] = useState(""); const [taskId, setTaskId] = useState(""); const [submissionId, setSubmissionId] = useState("");
  const [studentFilter, setStudentFilter] = useState(""); const [search, setSearch] = useState(""); const [loading, setLoading] = useState(!preview); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [notice, setNotice] = useState("");
  const receipts = useRef(new Map<string, string>());
  const uploaded = useRef(new WeakMap<File, string>());
  const rows = (resource: string) => !preview && dataOwner !== viewerId ? [] : data[resource] ?? [];
  const row = (resource: string, id: unknown) => rows(resource).find(r => r.id === id);
  const localText = (item: Row | undefined, field: string) => {
    if (!item) return "";
    const translation = rows("content_translations").find(r => r.resource_id === item.id && r.locale === lang);
    const fields = translation?.fields;
    if (fields && typeof fields === "object" && field in fields && typeof (fields as Record<string, unknown>)[field] === "string") return (fields as Record<string, string>)[field];
    return str(item, `${field}_${lang}`) || str(item, field);
  };
  const hasTranslation = (item: Row | undefined, field: string) => {
    if (!item) return false;
    const fields = rows("content_translations").find(r => r.resource_id === item.id && r.locale === lang)?.fields;
    return typeof item[`${field}_${lang}`] === "string" || Boolean(fields && typeof fields === "object" && typeof (fields as Record<string, unknown>)[field] === "string");
  };
  const displayDate = (date: unknown, time = false) => typeof date === "string" && !Number.isNaN(Date.parse(date)) ? new Intl.DateTimeFormat(lang === "es" ? "es-CO" : "en-US", { dateStyle: "medium", ...(time ? { timeStyle: "short" as const } : {}), timeZone: "America/Bogota" }).format(new Date(date)) : "—";
  const subjectName = (g: Row | undefined) => localText(row("subjects", g?.subject_id), "name");
  const personName = (id: unknown) => str(rows("roster").find(p => p.student_id === id) ?? row("profiles", id), "full_name", id === viewerId ? viewerName : id === rows("tasks").find(task => task.id === taskId)?.author_id ? t("Docente", "Teacher") : t("Estudiante", "Student"));
  const load = useCallback(async () => {
    if (preview || !user || !role) return;
    const generation = ++loadGeneration.current;
    const resources = role === "system_admin" ? systemResources : role === "academic_admin" ? adminResources : academicResources;
    const results = await Promise.allSettled(resources.map(async resource => [resource, await api.list<Row>(resource, { limit: 100 })] as const));
    const snapshot: Dataset = {}; let failed = false;
    results.forEach(result => { if (result.status === "fulfilled") snapshot[result.value[0]] = result.value[1]; else failed = true; });
    if (role === "teacher" && group) {
      try { snapshot.roster = (await api.command<Row[]>("group_roster", { p_group: group })).map(p => ({ ...p, id: str(p, "student_id") })); } catch { failed = true; }
    }
    if (generation !== loadGeneration.current) return;
    dataRef.current = snapshot; setDataOwner(user.profile.id); setData(snapshot); setLoading(false);
    if (failed) setError(lang === "es" ? "Parte de la información no pudo cargarse. Actualiza para intentarlo de nuevo; no se sustituyeron tus datos por ejemplos." : "Some information could not be loaded. Refresh to try again; your data has not been replaced with examples.");
  }, [api, preview, user, role, group, lang]);
  useEffect(() => { if (!preview && user) { setLoading(true); void load(); } if (!preview && !user) { loadGeneration.current++; dataRef.current = {}; setData({}); setDataOwner(""); } }, [load, preview, user]);
  useEffect(() => {
    if (!previewRole) return;
    const snapshot = selectPreview(previewStore, previewRole);
    dataRef.current = snapshot; setData(snapshot); setDataOwner(viewerId);
  }, [previewStore, previewRole, viewerId]);

  async function command(operation: string, params: Record<string, unknown>) {
    setBusy(true); setError(""); setNotice("");
    try {
      let result: unknown;
      if (preview && previewRole) {
        const next = changePreview(before => {
          const changed = simulate(before, operation, params, viewerId);
          result = operation === "publish_task" ? changed.tasks.filter(item => !before.tasks.some(old => old.id === item.id)).map(item => item.id) : operation === "add_comment" ? changed.comments[changed.comments.length - 1]?.id : params.p_submission;
          return changed;
        });
        const snapshot = selectPreview(next, previewRole); dataRef.current = snapshot; setData(snapshot);
      }
      else {
        const body = JSON.stringify([operation, params]);
        if (!receipts.current.has(body)) receipts.current.set(body, crypto.randomUUID());
        const receiptKey = receipts.current.get(body)!;
        result = operation === "invite" ? await api.invite(String(params.email), String(params.full_name), String(params.role), receiptKey) : operation === "execute_deletion" ? await api.executeDeletion(String(params.id)) : await api.command(operation, params, idempotent.includes(operation) ? receiptKey : undefined);
        await load();
      }
      setNotice(preview ? t("Cambio realizado en la vista previa. No se modificaron datos institucionales.", "Preview updated. Institutional data has not been changed.") : t("Operación completada.", "Operation completed."));
      return result;
    } catch (e) { const message = lang === "es" && e instanceof Error ? e.message : "The operation could not be completed. Check your permissions and try again."; setError(message); throw e; }
    finally { setBusy(false); }
  }
  function navigate(next: View) { if (!canOpenPortalView(next, role, permissions)) return; setView(next); setSearch(""); setError(""); setNotice(""); if (next !== "detail" && next !== "tasks") { setStudentFilter(""); setTaskId(""); setSubmissionId(""); } }
  function openTask(task: Row, submission?: Row) { setTaskId(task.id); setSubmissionId(submission?.id ?? ""); setGroup(str(task, "group_id")); navigate("detail"); }
  async function upload(files: File[]) {
    if (files.length > 3) throw new Error(t("Puedes adjuntar hasta tres archivos.", "You can attach up to three files."));
    if (files.some(file => !["application/pdf", "image/png", "image/jpeg"].includes(file.type) || file.size === 0 || file.size > 2000000)) throw new Error(t("Usa archivos PDF, JPG o PNG de hasta 2 MB.", "Use PDF, JPG or PNG files up to 2 MB."));
    const ids: string[] = [];
    for (const file of files) {
      if (!["application/pdf", "image/png", "image/jpeg"].includes(file.type) || file.size === 0 || file.size > 2000000) throw new Error(t("Usa archivos PDF, JPG o PNG de hasta 2 MB.", "Use PDF, JPG or PNG files up to 2 MB."));
      const existing = uploaded.current.get(file);
      if (existing) { ids.push(existing); continue; }
      if (preview && previewRole) { const id = crypto.randomUUID(); previewFiles[id] = file; const next = changePreview(current => ({ ...current, uploads: [...(current.uploads ?? []), { id, owner_id: viewerId, name: file.name, bytes: file.size, mime_type: file.type }] })); const snapshot = selectPreview(next, previewRole); dataRef.current = snapshot; setData(snapshot); uploaded.current.set(file, id); ids.push(id); }
      else { const id = await prepareEvidence(api, file); uploaded.current.set(file, id); ids.push(id); }
    }
    return ids;
  }
  async function download(file: Row) {
    try { const blob = preview ? previewFiles[file.id] : await api.download(file.id); if (!blob) throw new Error(); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = str(file, "name", `evidencia-${file.id}.${str(file, "mime_type").includes("pdf") ? "pdf" : "jpg"}`); a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
    catch { setError(t("No se pudo descargar el archivo.", "The file could not be downloaded.")); }
  }
  async function roster(ids: string[]) {
    if (preview) { const members = rows("enrollments").filter(e => ids.includes(str(e, "group_id"))).map(e => e.student_id); return rows("roster").filter(p => members.includes(p.student_id)); }
    const lists = await Promise.all(ids.map(id => api.command<Row[]>("group_roster", { p_group: id })));
    return Array.from(new Map(lists.flat().map(p => [p.student_id, { ...p, id: str(p, "student_id") }])).values());
  }
  if (!role || (!preview && !user)) return <><PublicHeader /><main className="private-gate"><Icon name="shield" size={40} /><h1>{t("Tu espacio es privado.", "Your space is private.")}</h1><p>{t("Ingresa con tu cuenta institucional para continuar. Si recargaste la página, inicia sesión otra vez.", "Sign in with your institutional account to continue. If you reloaded the page, sign in again.")}</p><Link href="/acceso" className="button button-primary">{t("Iniciar sesión", "Sign in")}</Link><Link href="/vista-previa" className="text-link">{t("Explorar una vista previa", "Explore a preview")}<Icon name="arrow" /></Link></main></>;

  const student = role === "student"; const teacher = role === "teacher"; const system = role === "system_admin"; const academic = role === "academic_admin";
  const menu: { id: View; es: string; en: string; icon: IconName }[] = [
    { id: "overview", es: "Mi inicio", en: "Overview", icon: "grid" },
    ...(student || teacher ? [{ id: "courses" as View, es: teacher ? "Mis grupos" : "Mis materias", en: teacher ? "My groups" : "My courses", icon: "book" as IconName }, { id: "tasks" as View, es: teacher ? "Entregas" : "Mis tareas", en: teacher ? "Submissions" : "Assignments", icon: "file" as IconName }] : []),
    ...(student ? [{ id: "grades" as View, es: "Calificaciones", en: "Grades", icon: "check" as IconName }] : []),
    ...(academic ? [{ id: "structure" as View, es: "Gestión académica", en: "Academic management", icon: "book" as IconName }] : []),
    ...(system ? [{ id: "users" as View, es: "Usuarios", en: "Accounts", icon: "user" as IconName }, { id: "audit" as View, es: "Actividad y bajas", en: "Activity and removal", icon: "shield" as IconName }] : []),
    ...(!system ? [{ id: "calendar" as View, es: "Calendario", en: "Calendar", icon: "calendar" as IconName }] : []),
    ...(academic && (preview || user?.permissions.some(p => p.permission === "contact.manage")) ? [{ id: "contacts" as View, es: "Consultas de contacto", en: "Contact requests", icon: "mail" as IconName }] : []),
    { id: "notifications", es: "Notificaciones", en: "Notifications", icon: "bell" }, { id: "profile", es: "Mi perfil", en: "My profile", icon: "user" }, { id: "security", es: "Seguridad", en: "Security", icon: "settings" },
  ];
  const selectedTask = row("tasks", taskId); const selectedSubmission = row("submissions", submissionId) ?? rows("submissions").find(s => s.task_id === taskId && s.student_id === viewerId);
  const visibleTasks = rows("tasks").filter(task => (!group || task.group_id === group) && (localText(task, "title").toLowerCase().includes(search.toLowerCase()) || subjectName(row("groups", task.group_id)).toLowerCase().includes(search.toLowerCase())));
  const pending = rows("submissions").filter(s => student ? number(s, "current_version") === 0 : number(s, "current_version") > 0 && s.grade === null);
  const visibleMenu = menu.filter(item => canOpenPortalView(item.id, role, permissions));
  const currentMenu = visibleMenu.find(m => m.id === view);
  const action = async (operation: string, params: Record<string, unknown>) => { try { return await command(operation, params); } catch { return undefined; } };
  const status = (s: Row | undefined) => !s || number(s, "current_version") === 0 ? t("Sin entregar", "Not submitted") : s.grade !== null ? t("Calificada", "Graded") : t("Por revisar", "Awaiting review");
  return <div className="portal"><a className="skip-link" href="#main">{t("Ir al contenido", "Skip to content")}</a><header className="portal-top"><Logo /><div className="portal-user"><span className="avatar">{viewerName.split(" ").slice(0, 2).map(n => n[0]).join("")}</span><div><strong>{viewerName}</strong><small>{roleNames[role][lang]}</small></div><Preferences /><button className="icon-button" aria-label={t("Cerrar sesión", "Sign out")} onClick={async () => { if (!preview) await logout(); router.push(preview ? "/vista-previa" : "/acceso"); }}><Icon name="logout" size={18} /></button></div></header>
    {preview && <div className="preview-banner" role="note">{t("Vista previa · Cambios solo en esta sesión", "Preview · Changes stay in this session")}</div>}
    <div className="portal-layout"><nav className="portal-sidebar" aria-label={t("Menú del campus", "Campus menu")}>{visibleMenu.map(item => <button key={item.id} aria-current={view === item.id || (item.id === "tasks" && (view === "detail" || view === "new-task")) ? "page" : undefined} onClick={() => navigate(item.id)}><Icon name={item.icon} />{lang === "es" ? item.es : item.en}</button>)}<div className="sidebar-bottom"><Link href="/"><Icon name="arrow" size={15} />{t("Volver al instituto", "Back to the institute")}</Link><p>Instituto Tecnológico<br />de San Miguel</p></div></nav><main className="portal-main" id="main"><div className="portal-page-heading"><div><h1>{view === "new-task" ? t("Una nueva oportunidad de aprender", "A new opportunity to learn") : view === "detail" ? localText(selectedTask, "title") : currentMenu ? lang === "es" ? currentMenu.es : currentMenu.en : "Campus"}</h1><p>{view === "overview" ? t("Todo lo importante para tu jornada académica.", "Everything that matters for your academic day.") : roleNames[role][lang]}</p></div>{teacher && view !== "new-task" && <button className="button button-primary" onClick={() => navigate("new-task")}><Icon name="plus" size={17} />{t("Nueva tarea", "New assignment")}</button>}{!preview && <button className="button button-secondary" disabled={loading || busy} onClick={() => { setError(""); void load(); }}>{t("Actualizar", "Refresh")}</button>}</div>
    {error && <div className="portal-error"><Message error>{error} {!preview && <button className="small-link" onClick={() => navigate("security")}>{t("Revisar seguridad", "Review security")}</button>}</Message></div>}{notice && <div className="portal-error"><Message>{notice}</Message></div>}
    {view === "security" ? <SecurityPanel preview={preview} busy={busy} /> : loading || (!preview && dataOwner !== viewerId) ? <div aria-busy="true" aria-label={t("Cargando", "Loading")}><div className="skeleton" /><div className="skeleton" /><div className="skeleton" /></div> : <>
    {view === "overview" && <><section className="overview-greeting"><div><h2>{t("Hola", "Hello")}, {viewerName.split(" ")[0]}.</h2><p>{student ? t("Cada entrega es un paso más. Encuentra aquí lo que sigue.", "Every submission is another step. Find what comes next here.") : teacher ? t("Tus grupos y sus próximos pasos, en un solo lugar.", "Your groups and their next steps, all in one place.") : t("Organiza el instituto desde un espacio claro y seguro.", "Manage the institute from a clear and secure workspace.")}</p></div><button className="button button-primary" onClick={() => navigate(student || teacher ? "courses" : system ? "users" : canOpenPortalView("structure", role, permissions) ? "structure" : can("contact.manage") ? "contacts" : "profile")}>{student ? t("Ir a mis materias", "Go to my courses") : teacher ? t("Ver mis grupos", "View my groups") : t("Comenzar", "Get started")}<Icon name="arrow" size={17} /></button></section><div className="overview-stats"><div><strong>{system ? rows("profiles").length : rows("groups").length}</strong><span>{system ? t("Cuentas visibles", "Visible accounts") : t("Grupos disponibles", "Available groups")}</span></div>{(student || teacher) && <><div><strong>{pending.length}</strong><span>{student ? t("Tareas sin entregar", "Unsubmitted assignments") : t("Entregas por revisar", "Submissions to review")}</span></div><div><strong>{rows("tasks").length}</strong><span>{t("Actividades", "Activities")}</span></div></>}{(system || academic) && <div><strong>{rows(system ? "deletion_requests" : "programs").length}</strong><span>{system ? t("Solicitudes de baja", "Removal requests") : t("Programas", "Programs")}</span></div>}</div>{(student || teacher) ? <section className="work-section"><h2>{t("Lo que sigue", "What's next")}</h2>{rows("tasks").slice(0, 5).map(task => <button key={task.id} className="list-row" onClick={() => { setGroup(str(task, "group_id")); if (teacher) { setView("tasks"); } else openTask(task); }}><div><strong>{localText(task, "title")}</strong><p>{subjectName(row("groups", task.group_id))} · {displayDate(task.due_at)}</p></div><Icon name="chevron" size={18} /></button>)}{!rows("tasks").length && <Empty title={t("Todo al día", "All caught up")} description={t("Las próximas actividades aparecerán aquí.", "Upcoming activities will appear here.")} />}</section> : <Message>{system ? t("Administrar cuentas no concede acceso a las calificaciones. Las operaciones sensibles requieren verificación adicional y quedan registradas.", "Managing accounts does not grant access to grades. Sensitive operations require additional verification and are recorded.") : t("Los permisos de estructura, matrículas, evaluación y cierre se verifican por separado en cada operación.", "Structure, enrollment, evaluation and closing permissions are checked separately for each operation.")}</Message>}</>}
    {view === "courses" && <><div className="table-tools"><div className="search-input"><Icon name="search" size={17} /><input aria-label={t("Buscar materia o grupo", "Search courses or groups")} placeholder={t("Buscar materia o grupo…", "Search courses or groups…")} value={search} onChange={e => setSearch(e.target.value)} /></div></div><Table headings={[t("Grupo y materia", "Group and course"), t("Período", "Term"), t("Actividades", "Activities"), ""]} empty={t("No hay grupos para mostrar.", "No groups to display.")}>{rows("groups").filter(g => `${g.name} ${subjectName(g)}`.toLowerCase().includes(search.toLowerCase())).map(g => <tr key={g.id}><td><strong>{subjectName(g)}</strong><p>{str(g, "name")}</p></td><td>{localText(row("periods", g.period_id), "name")}</td><td>{rows("tasks").filter(task => task.group_id === g.id).length}</td><td><button className="button button-secondary" onClick={() => { setGroup(g.id); navigate("tasks"); }}>{t("Abrir grupo", "Open group")}<Icon name="arrow" size={15} /></button></td></tr>)}</Table></>}
    {view === "tasks" && <><div className="table-tools"><div className="search-input"><Icon name="search" size={17} /><input aria-label={t("Buscar tarea", "Search assignments")} placeholder={t("Buscar tarea…", "Search assignments…")} value={search} onChange={e => setSearch(e.target.value)} /></div><select aria-label={t("Filtrar grupo", "Filter group")} value={group} onChange={e => setGroup(e.target.value)}><option value="">{t("Todos mis grupos", "All my groups")}</option>{rows("groups").map(g => <option key={g.id} value={g.id}>{str(g, "name")} · {subjectName(g)}</option>)}</select></div>{teacher && group && <details className="detail-panel work-section"><summary>{t("Estudiantes de este grupo", "Students in this group")}</summary>{rows("roster").filter(person => rows("enrollments").some(e => e.group_id === group && e.student_id === person.student_id)).map(person => <button key={person.id} className="list-row" onClick={() => setStudentFilter(str(person, "student_id", person.id))}><strong>{str(person, "full_name")}</strong><span>{t("Ver sus tareas", "View assignments")}</span><Icon name="chevron" size={16} /></button>)}</details>}{teacher && studentFilter && <div className="inline-actions work-section"><strong>{personName(studentFilter)}</strong><button className="small-link" onClick={() => setStudentFilter("")}>{t("Ver todo el grupo", "View entire group")}</button></div>}<Table headings={[t("Actividad", "Assignment"), t("Fecha límite", "Due date"), t("Estado", "Status"), ""]} empty={t("No hay actividades con este filtro.", "No assignments match this filter.")}>{visibleTasks.map(task => { const subs = rows("submissions").filter(s => s.task_id === task.id && (!studentFilter || s.student_id === studentFilter)); const own = subs.find(s => s.student_id === viewerId); return <tr key={task.id}><td><strong>{localText(task, "title")}</strong><p>{subjectName(row("groups", task.group_id))} · {str(row("groups", task.group_id), "name")}</p></td><td>{displayDate(task.due_at, true)}{Date.parse(str(task, "due_at")) < Date.now() && (!own || number(own, "current_version") === 0) && <p className="badge badge-warning">{t("Plazo vencido · Entrega permitida", "Past deadline · Submission allowed")}</p>}</td><td>{teacher ? <span className="badge">{subs.filter(s => number(s, "current_version") > 0 && s.grade === null).length} {t("por revisar", "to review")}</span> : <span className={`badge ${own?.grade === null && number(own, "current_version") === 0 ? "badge-warning" : ""}`}>{status(own)}</span>}</td><td><button className="button button-secondary" onClick={() => openTask(task, teacher && studentFilter ? subs[0] : undefined)}>{teacher ? t("Revisar", "Review") : t("Abrir tarea", "Open assignment")}<Icon name="arrow" size={15} /></button></td></tr>; })}</Table></>}
    {view === "detail" && selectedTask && <><button className="back-button" onClick={() => navigate("tasks")}><Icon name="arrow" size={16} />{t("Volver a las actividades", "Back to assignments")}</button><div className="portal-columns"><section className="detail-panel"><h2>{subjectName(row("groups", selectedTask.group_id))}</h2><p>{localText(selectedTask, "description")}</p>{lang === "en" && !str(selectedTask, "description_en") && !rows("content_translations").some(r => r.resource_id === selectedTask.id && r.locale === "en") && <p className="translation-note">Original. {t("Traducción revisada aún no disponible.", "A reviewed translation is not available yet.")}</p>}<div className="detail-meta"><span>{t("Fecha límite", "Due date")}: {displayDate(selectedTask.due_at, true)}</span><span>{t("Grupo", "Group")}: {str(row("groups", selectedTask.group_id), "name")}</span></div>{teacher && !selectedSubmission ? <><h3>{t("Entregas del grupo", "Group submissions")}</h3>{rows("submissions").filter(s => s.task_id === selectedTask.id).map(s => <button key={s.id} className="list-row" onClick={() => setSubmissionId(s.id)}><div><strong>{personName(s.student_id)}</strong><p>{status(s)}</p></div><span className="grade">{s.grade !== null ? Number(s.grade).toFixed(1) : "—"}</span><Icon name="chevron" size={16} /></button>)}</> : <SubmissionPanel task={selectedTask} submission={selectedSubmission} history={rows("grade_history")} versions={rows("submission_versions")} comments={rows("comments")} uploads={rows("uploads")} teacher={teacher} preview={preview} busy={busy} person={personName} text={localText} translated={hasTranslation} date={displayDate} command={command} upload={upload} download={download} />}</section><aside className="detail-panel"><h2>{t("Ten presente", "Keep in mind")}</h2><p>{t("La entrega es única. Cualquier reemplazo requiere autorización del docente. Puedes entregar fuera de plazo: el retraso quedará indicado sin una penalización automática.", "There is one confirmed submission. Any replacement requires teacher authorization. Late work is accepted: the delay is recorded without an automatic penalty.")}</p><RubricPanel task={selectedTask.id} record={rows("rubrics").find(item => item.task_id === selectedTask.id)} teacher={teacher} command={command} busy={busy} /><h3>{t("Evaluación", "Assessment")}</h3><p>{localText(row("categories", selectedTask.category_id), "name")} · {number(row("categories", selectedTask.category_id), "weight")}%</p>{selectedSubmission?.grade !== null && selectedSubmission?.grade !== undefined && <div className="overview-stats"><div><strong>{Number(selectedSubmission.grade).toFixed(1)} <small>/ 5.0</small></strong><span>{t("Calificación visible al guardar", "Grade visible when saved")}</span></div></div>}{teacher && <p className="operation-note">{t("Las calificaciones se muestran al estudiante inmediatamente al guardarlas.", "Grades become visible to the student immediately when saved.")}</p>}</aside></div></>}
    {view === "new-task" && teacher && <NewTask groups={rows("groups")} categories={rows("categories")} subjectName={subjectName} roster={roster} busy={busy} command={command} onDone={() => navigate("tasks")} />}
    {view === "grades" && student && <><Message>{t("Las notas son individuales. El resultado definitivo se determina al cerrar el período, después del redondeo a un decimal. La nota mínima aprobatoria es 3.0.", "Grades are individual. Final results are determined when the term closes, after rounding to one decimal. The minimum passing grade is 3.0.")}</Message><section className="work-section"><h2>{t("Mis calificaciones", "My grades")}</h2><Table headings={[t("Actividad", "Assignment"), t("Materia", "Course"), t("Nota", "Grade"), t("Estado", "Status")]} empty={t("Tus notas aparecerán cuando el docente las guarde.", "Your grades will appear when your teacher saves them.")}>{rows("submissions").map(s => { const task = row("tasks", s.task_id); return <tr key={s.id}><td>{localText(task, "title")}</td><td>{subjectName(row("groups", task?.group_id))}</td><td className="grade">{s.grade !== null ? `${Number(s.grade).toFixed(1)} / 5.0` : "—"}</td><td>{status(s)}</td></tr>; })}</Table></section><section className="work-section"><h2>{t("Resultados por materia", "Course results")}</h2>{rows("groups").map(g => <CourseResult key={g.id} group={g} name={subjectName(g)} preview={preview} result={rows("final_results").find(r => r.group_id === g.id)} submissions={rows("submissions").filter(s => row("tasks", s.task_id)?.group_id === g.id)} />)}</section></>}
    {view === "calendar" && <><section className="calendar-list">{[...rows("calendar_events"), ...rows("tasks").map(task => ({ ...task, starts_at: task.due_at }))].sort((a, b) => Date.parse(str(a, "starts_at")) - Date.parse(str(b, "starts_at"))).map(event => <div className="list-row" key={event.id}><Icon name="calendar" /><div><strong>{localText(event, "title")}</strong><p>{displayDate(event.starts_at, true)}</p></div></div>)}{!rows("calendar_events").length && !rows("tasks").length && <Empty title={t("Un calendario por escribir", "An open calendar")} description={t("Las actividades y eventos académicos aparecerán aquí.", "Academic activities and events will appear here.")} />}</section>{academic && can("structure.manage") && <EventForm periods={rows("periods")} command={command} busy={busy} />}</>}
    {view === "notifications" && <><button className="button button-secondary" disabled={busy} onClick={() => void action("mark_all_notifications", {})}>{t("Marcar todas como leídas", "Mark all as read")}</button><section className="work-section">{rows("notifications").map(n => <button key={n.id} className={`list-row ${n.read_at ? "" : "notification-unread"}`} onClick={() => void action("mark_notification", { p_notification: n.id })}><Icon name="bell" /><div><strong>{localText(n, "title") || t("Tienes una actualización académica", "You have an academic update")}</strong><p>{displayDate(n.created_at, true)}</p></div><span className="badge">{n.read_at ? t("Leída", "Read") : t("Nueva", "New")}</span></button>)}{!rows("notifications").length && <Empty title={t("Todo al día", "All caught up")} description={t("No tienes notificaciones.", "You have no notifications.")} />}</section></>}
    {view === "profile" && <ProfilePanel avatarFile={rows("uploads").find(file => file.path === (preview ? rows("profiles").find(p => p.id === viewerId)?.avatar_path : user?.profile.avatar_path))} profile={preview ? rows("profiles").find(p => p.id === viewerId)! : user!.profile as unknown as Row} program={localText(row("programs", preview ? rows("profiles").find(p => p.id === viewerId)?.program_id : user?.profile.program_id), "name")} command={command} busy={busy} preview={preview} />}
    {view === "users" && system && <AccountPanel data={data} command={command} busy={busy} />}
    {view === "structure" && academic && <><AcademicPanel data={data} command={command} busy={busy} text={localText} can={can} /><ManagementTools data={data} command={command} busy={busy} can={can} /></>}
    {view === "contacts" && academic && <ContactInbox records={rows("contact_inquiries")} command={command} busy={busy} />}
    {view === "audit" && system && <AuditPanel data={data} viewerId={viewerId} command={command} busy={busy} date={displayDate} />}
    </>}{!preview && Object.values(data).some(list => list.length >= 100) && <p className="operation-note">{t("Esta vista muestra hasta 100 registros por sección. Filtra por grupo para acotar la consulta.", "This view shows up to 100 records per section. Filter by group to narrow your query.")}</p>}</main></div></div>;
}

function Table({ headings, children, empty }: { headings: string[]; children: ReactNode; empty: string }) { const { t } = useUI(); const hasRows = Array.isArray(children) ? children.length > 0 : Boolean(children); return hasRows ? <div className="table-wrap" role="region" aria-label={t("Tabla de información", "Information table")}><table><thead><tr>{headings.map((heading, i) => <th key={i} scope="col">{heading || <span className="sr-only">{t("Acciones", "Actions")}</span>}</th>)}</tr></thead><tbody>{children}</tbody></table></div> : <Empty title={t("Sin resultados", "No results")} description={empty} />; }

function CourseResult({ group, name, preview, result, submissions }: { group: Row; name: string; preview: boolean; result?: Row; submissions: Row[] }) {
  const { api, t } = useUI(); const [summary, setSummary] = useState<Row | null>(null);
  useEffect(() => { let canceled = false; if (!preview) void api.command<Row[]>("my_subject_result", { p_group: group.id }).then(rows => { if (!canceled) setSummary(Array.isArray(rows) ? rows[0] : rows); }).catch(() => { if (!canceled) setSummary(null); }); return () => { canceled = true; }; }, [api, group.id, preview]);
  const graded = submissions.filter(s => s.grade !== null); const sample = graded.length ? graded.reduce((sum, s) => sum + Number(s.grade), 0) / graded.length : null; const provisional = summary?.provisional && typeof summary.provisional === "object" ? (summary.provisional as { value?: number | null }).value : null;
  return <div className="list-row"><div><strong>{name}</strong><p>{result ? t("Período cerrado", "Closed term") : preview ? t("Promedio de muestra · Período abierto", "Sample average · Open term") : t("Promedio provisional · Política académica pendiente", "Provisional average · Academic policy pending")}</p></div><div><strong className="grade">{result ? Number(result.final_grade).toFixed(1) : preview && sample !== null ? sample.toFixed(2) : provisional !== undefined && provisional !== null ? Number(provisional).toFixed(2) : "—"}</strong>{result && <p>{result.passed ? t("Aprobada", "Passed") : t("No aprobada", "Not passed")}</p>}</div></div>;
}

function SubmissionPanel({ task, submission, history, versions, comments, uploads, teacher, preview, busy, person, text, translated, date, command, upload, download }: { task: Row; submission?: Row; history: Row[]; versions: Row[]; comments: Row[]; uploads: Row[]; teacher: boolean; preview: boolean; busy: boolean; person: (id: unknown) => string; text: (row: Row | undefined, field: string) => string; translated: (row: Row | undefined, field: string) => boolean; date: (date: unknown, time?: boolean) => string; command: Command; upload: (files: File[]) => Promise<string[]>; download: (file: Row) => Promise<void> }) {
  const { t, lang } = useUI(); const [working, setWorking] = useState(false); const [error, setError] = useState(""); const [original, setOriginal] = useState(false);
  const pendingFiles = useRef<{ signature: string; ids: string[] } | null>(null);
  if (!submission) return <Empty title={t("Selecciona una entrega", "Select a submission")} description={t("Las entregas de los destinatarios aparecerán aquí.", "Recipient submissions will appear here.")} />;
  const ownVersions = versions.filter(v => v.submission_id === submission.id).sort((a, b) => number(b, "version") - number(a, "version")); const current = ownVersions.find(v => v.version === submission.current_version);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (!submission) return; const data = new FormData(event.currentTarget); setWorking(true); setError("");
    try {
      const files = data.getAll("files").filter((f): f is File => f instanceof File && f.size > 0); const signature = files.map(f => `${f.name}:${f.size}:${f.lastModified}`).join("|");
      if (!pendingFiles.current || signature !== pendingFiles.current.signature) pendingFiles.current = { signature, ids: await upload(files) };
      // Los archivos verificados se reutilizan al repetir una confirmación fallida.
      await command("submit_work", { p_submission: submission.id, p_body: String(data.get("body")), p_uploads: pendingFiles.current.ids }); pendingFiles.current = null;
    } catch (e) { setError(lang === "es" && e instanceof Error ? e.message : "Submission could not be completed. Your text and files remain available to retry."); } finally { setWorking(false); }
  }
  async function comment(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (!submission) return; const form = event.currentTarget; const data = new FormData(form); setWorking(true); setError("");
    try { const id = await command("add_comment", { p_submission: submission.id, p_body: String(data.get("comment")) }); const english = String(data.get("english") || "").trim(); if (english && typeof id === "string") await command("set_translation", { p_kind: "comment", p_id: id, p_locale: "en", p_fields: { body: english } }); form.reset(); }
    catch { setError(t("Revisa el estado del comentario antes de volver a enviarlo. Si falló la traducción, el original puede haberse guardado.", "Check the comment status before sending it again. If translation failed, the original may have been saved.")); } finally { setWorking(false); }
  }
  async function grade(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!submission) return; const data = new FormData(event.currentTarget); try { await command("review_work", { p_submission: submission.id, p_action: "grade", p_grade: Number(data.get("grade")), p_comment: String(data.get("reason")) }); } catch { /* El error se presenta en el contenedor. */ } }
  return <><h3>{teacher ? person(submission.student_id) : t("Tu entrega", "Your submission")}</h3>{current ? <><div className="detail-meta"><span>{t("Versión", "Version")} {number(current, "version")} · {date(current.submitted_at, true)}</span>{Boolean(current.late) && <span className="badge badge-warning">{t("Fuera de plazo · Sin descuento automático", "Late · No automatic deduction")}</span>}</div><p style={{ whiteSpace: "pre-wrap" }}>{original ? str(current, "body") : text(current, "body")}</p>{lang === "en" && (translated(current, "body") ? <button className="small-link" onClick={() => setOriginal(!original)}>{original ? "View translation" : "View original"}</button> : <p className="translation-note">Original · Reviewed translation not available</p>)}{uploads.filter(f => f.version_id === current.id || (Array.isArray(current.upload_ids) && current.upload_ids.includes(f.id))).map(file => <button key={file.id} className="list-row" onClick={() => void download(file)}><Icon name="file" /><span>{str(file, "name", t("Archivo de evidencia", "Evidence file"))}</span><Icon name="download" size={17} /></button>)}<p className="operation-note">{t("Entrega confirmada. Conservamos la fecha, la versión y las evidencias.", "Submission confirmed. Date, version and evidence are retained.")}{preview && ` ${t("Archivos solo en memoria; no se enviaron a un servidor.", "Files are held in memory only; nothing was sent to a server.")}`}</p></> : <Message>{t("Aún no hay una entrega confirmada.", "No submission has been confirmed yet.")}</Message>}
    {!teacher && (number(submission, "current_version") === 0 || submission.replacement_allowed) && <form onSubmit={submit}><h3>{number(submission, "current_version") ? t("Reemplazo autorizado", "Authorized replacement") : t("Preparar entrega", "Prepare submission")}</h3><label>{t("Tu respuesta", "Your response")}<textarea name="body" rows={5} maxLength={10000} required /></label><label>{t("Evidencias · PDF, JPG o PNG · Hasta 3 archivos de 2 MB", "Evidence · PDF, JPG or PNG · Up to 3 files, 2 MB each")}<input type="file" name="files" multiple accept="application/pdf,image/jpeg,image/png" /></label>{Date.parse(str(task, "due_at")) < Date.now() && <Message>{t("La fecha límite ya pasó. Puedes entregar y quedará registrado el retraso, sin descuento automático.", "The deadline has passed. You can submit; the delay will be recorded without an automatic deduction.")}</Message>}<button className="button button-primary" disabled={busy || working}>{working ? t("Confirmando…", "Confirming…") : t("Confirmar entrega", "Confirm submission")}<Icon name="upload" size={17} /></button></form>}
    {teacher && number(submission, "current_version") > 0 && <form onSubmit={grade}><h3>{t("Revisar y calificar", "Review and grade")}</h3><label>{t("Calificación · 0.0 a 5.0", "Grade · 0.0 to 5.0")}<input type="number" name="grade" min={0} max={5} step="0.01" defaultValue={submission.grade === null ? "" : Number(submission.grade)} required /></label><label>{t("Comentario o motivo de corrección", "Feedback or reason for correction")}<textarea name="reason" rows={3} required maxLength={10000} /></label><button disabled={busy} className="button button-primary">{t("Guardar calificación", "Save grade")}<Icon name="check" size={17} /></button></form>}
    {teacher && number(submission, "current_version") > 0 && <div className="inline-actions"><button className="button button-secondary" disabled={busy || Boolean(submission.replacement_allowed)} onClick={() => { void command("review_work", { p_submission: submission.id, p_action: "authorize_replacement", p_grade: null, p_comment: null }).catch(() => undefined); }}>{submission.replacement_allowed ? t("Reemplazo ya autorizado", "Replacement already authorized") : t("Autorizar un reemplazo", "Authorize a replacement")}</button></div>}
    {ownVersions.length > 1 && <details className="work-section"><summary>{t("Historial de versiones", "Version history")} ({ownVersions.length})</summary>{ownVersions.map(v => <div className="comment" key={v.id}><small>{t("Versión", "Version")} {number(v, "version")} · {date(v.submitted_at, true)} {v.late ? t("· Fuera de plazo", "· Late") : ""}</small><p>{text(v, "body")}</p></div>)}</details>}
    {history.some(item => item.submission_id === submission.id) && <details className="work-section"><summary>{t("Historial de calificaciones", "Grade history")}</summary>{history.filter(item => item.submission_id === submission.id).map(item => <div className="comment" key={item.id}><small>{date(item.created_at, true)}</small><p>{item.old_grade === null ? "—" : Number(item.old_grade).toFixed(1)} → {Number(item.new_grade).toFixed(1)} · {str(item, "reason")}</p></div>)}</details>}
    <h3>{t("Conversación de la entrega", "Submission conversation")}</h3>{comments.filter(c => c.submission_id === submission.id).map(c => <div key={c.id} className="comment"><small>{person(c.author_id)} · {date(c.created_at, true)}</small><p>{text(c, "body")}</p>{lang === "en" && !translated(c, "body") && <span className="translation-note">Original · {t("Traducción sujeta a revisión del autor", "Translation subject to author review")}</span>}</div>)}<form onSubmit={comment}><label>{t("Tu comentario", "Your comment")}<textarea name="comment" required rows={3} maxLength={10000} /></label><details><summary>{t("Añadir versión en inglés revisada por ti", "Add an English version reviewed by you")}</summary><textarea name="english" rows={3} maxLength={10000} aria-label={t("Versión del comentario en inglés", "English version of the comment")} /></details><button className="button button-secondary" disabled={busy || working}>{t("Enviar comentario", "Send comment")}<Icon name="arrow" size={17} /></button></form>{error && <Message error>{error}</Message>}
  </>;
}

function NewTask({ groups, categories, subjectName, roster, busy, command, onDone }: { groups: Row[]; categories: Row[]; subjectName: (g: Row) => string; roster: (ids: string[]) => Promise<Row[]>; busy: boolean; command: Command; onDone: () => void }) {
  const { t } = useUI(); const [selected, setSelected] = useState<string[]>([]); const [members, setMembers] = useState<Row[]>([]); const [specific, setSpecific] = useState(false); const [error, setError] = useState(""); const [filter, setFilter] = useState("");
  useEffect(() => { let canceled = false; if (!specific || !selected.length) { setMembers([]); return; } void roster(selected).then(rows => { if (!canceled) setMembers(rows); }).catch(() => { if (!canceled) setError(t("No se pudo cargar la lista de estudiantes.", "The student list could not be loaded.")); }); return () => { canceled = true; }; }, [selected, specific]); // La lista se consulta únicamente para los grupos elegidos.
  const selectedGroups = groups.filter(g => selected.includes(g.id));
  const names = [...new Set(categories.map(c => str(c, "name")))].filter(name => selectedGroups.length > 0 && selectedGroups.every(g => categories.some(c => c.subject_id === g.subject_id && c.period_id === g.period_id && c.name === name)));
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = event.currentTarget; const data = new FormData(form); setError("");
    const students = data.getAll("students").map(String); if (!selected.length || (specific && !students.length)) { setError(t("Elige grupos y al menos un destinatario cuando uses una lista específica.", "Choose groups and at least one recipient when using a specific list.")); return; }
    try { const ids = await command("publish_task", { p_groups: selected, p_title: String(data.get("title")), p_description: String(data.get("description")), p_due_at: new Date(String(data.get("due"))).toISOString(), p_category_name: String(data.get("category")), p_students: specific ? students : null });
      const title = String(data.get("title_en") || "").trim(); const description = String(data.get("description_en") || "").trim();
      if (title && description && Array.isArray(ids)) for (const id of ids.filter((id): id is string => typeof id === "string")) await command("set_translation", { p_kind: "task", p_id: id, p_locale: "en", p_fields: { title, description } });
      onDone();
    } catch { setError(t("No se pudo completar todo el proceso. Revisa las actividades creadas antes de repetir; una traducción puede haber quedado pendiente.", "The process could not be fully completed. Check created activities before retrying; a translation may still be pending.")); }
  }
  return <section className="detail-panel form-panel"><h2>{t("Define la actividad y sus destinatarios", "Define the assignment and its recipients")}</h2><form onSubmit={submit}><label>{t("Título", "Title")}<input name="title" required maxLength={200} /></label><label>{t("Instrucciones", "Instructions")}<textarea name="description" required rows={5} maxLength={10000} /></label><details><summary>{t("Añadir versión revisada en inglés", "Add a reviewed English version")}</summary><label>{t("Título en inglés", "English title")}<input name="title_en" maxLength={200} /></label><label>{t("Instrucciones en inglés", "English instructions")}<textarea name="description_en" rows={3} maxLength={10000} /></label></details><div className="form-two"><label>{t("Fecha y hora límite", "Due date and time")}<input type="datetime-local" name="due" required /></label><label>{t("Categoría de evaluación", "Assessment category")}<select name="category" required><option value="">{t("Elige una categoría", "Choose a category")}</option>{names.map(name => <option key={name}>{name}</option>)}</select></label></div><div><strong>{t("Grupos destinatarios", "Recipient groups")}</strong><div className="inline-actions"><button type="button" className="small-link" onClick={() => setSelected(groups.map(g => g.id))}>{t("Seleccionar todos", "Select all")}</button><button type="button" className="small-link" onClick={() => setSelected([])}>{t("Limpiar selección", "Clear selection")}</button></div><div className="check-list">{groups.map(g => <label key={g.id}><input type="checkbox" checked={selected.includes(g.id)} onChange={e => setSelected(e.target.checked ? [...selected, g.id] : selected.filter(id => id !== g.id))} />{str(g, "name")} · {subjectName(g)}</label>)}</div></div><label className="checkbox-label"><input type="checkbox" checked={specific} onChange={e => setSpecific(e.target.checked)} />{t("Asignar solo a estudiantes seleccionados", "Assign only to selected students")}</label>{specific && <><input aria-label={t("Buscar estudiantes", "Search students")} placeholder={t("Buscar estudiante…", "Search students…")} value={filter} onChange={e => setFilter(e.target.value)} /><div className="check-list">{members.map(p => <label key={p.id} hidden={!str(p, "full_name").toLowerCase().includes(filter.toLowerCase())}><input type="checkbox" name="students" value={str(p, "student_id", p.id)} />{str(p, "full_name")}</label>)}</div></>}<Message>{selected.length} {t("grupos seleccionados. Se comprobarán los destinatarios y las categorías antes de publicar.", "groups selected. Recipients and assessment categories will be checked before publishing.")}</Message>{error && <Message error>{error}</Message>}<button className="button button-primary" disabled={busy}>{t("Publicar actividad", "Publish assignment")}<Icon name="arrow" /></button></form></section>;
}

function ProfilePanel({ profile, program, command, busy, preview, avatarFile }: { avatarFile?: Row; profile: Row; program: string; command: Command; busy: boolean; preview: boolean }) {
  const { t, lang, api, refreshUser, previewFiles } = useUI(); const [error, setError] = useState(""); const [avatar, setAvatar] = useState(""); const avatarUrl = useRef("");
  useEffect(() => {
    let canceled = false;
    const fileId = avatarFile?.id;
    const existing = preview ? previewFiles[profile.id] : undefined;
    if (existing || (!preview && fileId)) {
      const pending = existing ? Promise.resolve(existing as Blob) : api.download(fileId!);
      void pending.then(blob => {
        if (canceled) return;
        if (avatarUrl.current) URL.revokeObjectURL(avatarUrl.current);
        avatarUrl.current = URL.createObjectURL(blob); setAvatar(avatarUrl.current);
      }).catch(() => { if (!canceled) setError(t("No se pudo cargar la foto privada.", "Your private photo could not be loaded.")); });
    }
    return () => { canceled = true; if (avatarUrl.current) URL.revokeObjectURL(avatarUrl.current); };
  }, [api, preview, previewFiles, profile.id, avatarFile?.id]);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); setError(""); try { await command("update_my_profile", { p_address: String(form.get("address")), p_avatar_path: str(profile, "avatar_path") || null }); if (!preview) await refreshUser(); } catch { /* Mensaje del contenedor. */ } }
  async function photo(file?: File) {
    if (!file) return; setError(""); try {
      if (!["image/jpeg", "image/png"].includes(file.type) || file.size > 2000000) throw new Error(t("Elige una foto JPG o PNG de hasta 2 MB.", "Choose a JPG or PNG photo up to 2 MB."));
      if (!preview) { const id = await prepareEvidence(api, file); const uploads = await api.list<Row>("uploads", { id }); await command("update_my_profile", { p_address: str(profile, "address"), p_avatar_path: str(uploads[0], "path") }); await refreshUser(); }
      if (preview) previewFiles[profile.id] = file;
      if (avatarUrl.current) URL.revokeObjectURL(avatarUrl.current); avatarUrl.current = URL.createObjectURL(file); setAvatar(avatarUrl.current);
    } catch (e) { setError(lang === "es" && e instanceof Error ? e.message : "Your photo could not be updated."); }
  }
  return <div className="portal-columns"><section className="detail-panel"><h2>{t("Tu información", "Your information")}</h2>{avatar && <Image src={avatar} width={90} height={90} unoptimized alt={t("Mi foto de perfil", "My profile photo")} style={{ borderRadius: "50%" }} />}<dl className="profile-grid">{[[t("Nombre", "Name"), str(profile, "full_name")], [t("Documento", "ID document"), str(profile, "document_number", "—")], [t("Fecha de nacimiento", "Date of birth"), str(profile, "birth_date", "—")], [t("Carrera", "Program"), program || "—"]].map(([name, value]) => <div key={name}><dt>{name}</dt><dd>{value}</dd></div>)}</dl><form onSubmit={submit}><label>{t("Dirección", "Address")}<input name="address" defaultValue={str(profile, "address")} maxLength={500} /></label><button disabled={busy} className="button button-primary">{t("Guardar dirección", "Save address")}</button></form><div className="work-section"><label>{t("Actualizar foto · JPG o PNG, máximo 2 MB", "Update photo · JPG or PNG, maximum 2 MB")}<input type="file" accept="image/jpeg,image/png" onChange={e => void photo(e.target.files?.[0])} /></label></div>{error && <Message error>{error}</Message>}</section><section className="detail-panel"><h2>{t("Corrección de datos", "Data correction")}</h2><p>{t("Tu nombre, documento, fecha de nacimiento y carrera solo pueden corregirse por personal autorizado. Envía una solicitud explicando el cambio.", "Your name, ID document, date of birth and program can only be corrected by authorized staff. Submit a request explaining the change.")}</p><form onSubmit={async e => { e.preventDefault(); const d = new FormData(e.currentTarget); try { await command("request_identity_change", { p_proposed: { full_name: String(d.get("name")) }, p_reason: String(d.get("reason")) }); } catch { /* Contenedor. */ } }}><label>{t("Nombre propuesto", "Proposed name")}<input name="name" required maxLength={200} /></label><label>{t("Motivo y datos que deben corregirse", "Reason and information to correct")}<textarea name="reason" rows={4} required maxLength={2000} /></label><button disabled={busy} className="button button-secondary">{t("Enviar solicitud", "Submit request")}</button></form></section></div>;
}

function SecurityPanel({ preview, busy }: { preview: boolean; busy: boolean }) {
  const { t, lang, api, reduced, setReduced, refreshUser } = useUI(); const [message, setMessage] = useState(""); const [error, setError] = useState(""); const [factor, setFactor] = useState<{ id: string; totp: { qr_code: string; secret: string; uri: string } } | null>(null); const [working, setWorking] = useState(false); const [factors, setFactors] = useState<{ id: string; friendly_name?: string; status: string }[]>([]);
  useEffect(() => { if (!preview) void api.listMfa().then(setFactors).catch(() => undefined); }, [api, preview]);
  async function verifyCode(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (working) return;
    const form = event.currentTarget; const fields = new FormData(form);
    setWorking(true); setError(""); setMessage("");
    let accepted = false;
    try {
      const factorId = String(fields.get("factor"));
      const challenge = await api.challengeMfa(factorId);
      await api.verifyMfa(factorId, challenge.id, String(fields.get("code")));
      accepted = true;
      setFactor(null); form.reset();
      setMessage(t("Verificación completada para esta sesión.", "Verification completed for this session."));
      await refreshUser();
      setFactors(await api.listMfa());
    } catch {
      setError(accepted
        ? t("El código fue aceptado, pero no se pudo actualizar toda la información. Vuelve a iniciar sesión y verifica con tu autenticador existente.", "The code was accepted, but some information could not be refreshed. Sign in again and verify with your existing authenticator.")
        : t("No se pudo verificar el código. Intenta con el siguiente.", "Could not verify the code. Try the next one."));
    } finally { setWorking(false); }
  }
  async function changePassword(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; const d = new FormData(form); setError(""); if (d.get("password") !== d.get("confirm")) { setError(t("Las contraseñas no coinciden.", "Passwords do not match.")); return; } setWorking(true); try { if (!preview) await api.changePassword(String(d.get("password"))); setMessage(preview ? t("Ejemplo de cambio de contraseña. No se modificó ninguna cuenta.", "Sample password change. No account has been changed.") : t("Contraseña actualizada.", "Password updated.")); form.reset(); } catch (e) { setError(lang === "es" && e instanceof Error ? e.message : "Password could not be changed."); } finally { setWorking(false); } }
  return <div className="portal-columns"><section className="detail-panel"><h2>{t("Cambiar contraseña", "Change password")}</h2><form onSubmit={changePassword}><label>{t("Nueva contraseña · Mínimo 12 caracteres", "New password · At least 12 characters")}<input type="password" name="password" required minLength={12} maxLength={128} autoComplete="new-password" /></label><label>{t("Confirmar contraseña", "Confirm password")}<input type="password" name="confirm" required minLength={12} maxLength={128} autoComplete="new-password" /></label><button className="button button-primary" disabled={working || busy}>{t("Actualizar contraseña", "Update password")}</button></form><h3>{t("Tus preferencias", "Your preferences")}</h3><Preferences /><label className="checkbox-label" style={{ marginTop: 20 }}><input type="checkbox" checked={reduced} onChange={e => setReduced(e.target.checked)} />{t("Reducir movimiento", "Reduce motion")}</label></section><section className="detail-panel"><h2>{t("Verificación en dos pasos", "Two-step verification")}</h2><p>{t("Las acciones administrativas sensibles requieren un código de una aplicación autenticadora. Nunca compartas la clave de configuración.", "Sensitive administrative actions require a code from an authenticator app. Never share the setup secret.")}</p>{preview ? <Message>{t("La inscripción del autenticador solo está disponible con una sesión institucional real.", "Authenticator enrollment is only available with a real institutional session.")}</Message> : <><button className="button button-secondary" style={{ marginTop: 20 }} disabled={working} onClick={async () => { setWorking(true); setError(""); try { setFactor(await api.enrollMfa()); } catch { setError(t("No se pudo inscribir otro factor. Si ya tienes uno, utiliza su identificador para verificarlo.", "Could not enroll another factor. If you already have one, use its identifier to verify it.")); } finally { setWorking(false); } }}>{t("Configurar autenticador", "Set up authenticator")}</button>{factor && <div className="work-section"><Image src={`data:image/svg+xml;charset=utf-8,${encodeURIComponent(factor.totp.qr_code)}`} unoptimized width={180} height={180} alt={t("Código QR privado para el autenticador", "Private authenticator QR code")} /><label>{t("Clave manual privada", "Private manual key")}<input value={factor.totp.secret} readOnly /></label></div>}<form onSubmit={verifyCode}><label>{t("Aplicación autenticadora", "Authenticator app")}<select name="factor" key={factor?.id} defaultValue={factor?.id || factors[0]?.id || ""} required><option value="">{t("Selecciona tu autenticador", "Select your authenticator")}</option>{factor && <option value={factor.id}>{t("Autenticador recién configurado", "Newly configured authenticator")}</option>}{factors.filter(item => item.id !== factor?.id).map(item => <option key={item.id} value={item.id}>{item.friendly_name || t("Mi autenticador", "My authenticator")}</option>)}</select></label><label>{t("Código de 6 dígitos", "6-digit code")}<input name="code" inputMode="numeric" pattern="[0-9]{6}" autoComplete="one-time-code" required maxLength={6} /></label><button className="button button-primary" disabled={working}>{t("Verificar código", "Verify code")}</button></form></>}{message && <Message>{message}</Message>}{error && <Message error>{error}</Message>}</section></div>;
}

function AccountPanel({ data, command, busy }: { data: Dataset; command: Command; busy: boolean }) {
  const { t, lang } = useUI(); const [search, setSearch] = useState(""); const [selected, setSelected] = useState<Row | null>(null);
  return <><div className="table-tools"><div className="search-input"><Icon name="search" /><input value={search} onChange={e => setSearch(e.target.value)} placeholder={t("Buscar usuario…", "Search accounts…")} aria-label={t("Buscar usuario", "Search accounts")} /></div></div><Table headings={[t("Usuario", "Account"), t("Estado", "State"), ""]} empty={t("No hay usuarios con ese nombre.", "No accounts match that name.")}>{(data.profiles ?? []).filter(p => str(p, "full_name").toLowerCase().includes(search.toLowerCase())).map(p => <tr key={p.id}><td><strong>{str(p, "full_name")}</strong><p>{str(p, "document_number")}</p></td><td><span className={`badge ${p.state === "suspended" ? "badge-warning" : ""}`}>{p.state === "active" ? t("Activa", "Active") : p.state === "suspended" ? t("Suspendida", "Suspended") : t("Archivada", "Archived")}</span></td><td><button className="button button-secondary" onClick={() => setSelected(p)}>{t("Gestionar", "Manage")}<Icon name="arrow" size={15} /></button></td></tr>)}</Table><div className="portal-columns work-section"><section className="detail-panel"><h2>{t("Invitar a una persona", "Invite a person")}</h2><p>{t("El usuario establecerá su contraseña mediante un enlace. No existe registro público.", "The user will set a password using a link. There is no public sign-up.")}</p><form onSubmit={async e => { e.preventDefault(); const form = e.currentTarget; const d = new FormData(form); try { await command("invite", { email: String(d.get("email")), full_name: String(d.get("name")), role: String(d.get("role")) }); form.reset(); } catch { /* Contenedor. */ } }}><label>{t("Nombre completo", "Full name")}<input name="name" required maxLength={200} /></label><label>{t("Correo institucional", "Institutional email")}<input name="email" type="email" required maxLength={254} /></label><label>{t("Rol", "Role")}<select name="role">{(Object.keys(roleNames) as Role[]).map(role => <option key={role} value={role}>{roleNames[role][lang]}</option>)}</select></label><button disabled={busy} className="button button-primary">{t("Iniciar invitación", "Start invitation")}<Icon name="mail" size={16} /></button></form></section><section className="detail-panel"><h2>{selected ? str(selected, "full_name") : t("Gestionar una cuenta", "Manage an account")}</h2>{selected ? <><form onSubmit={async e => { e.preventDefault(); const d = new FormData(e.currentTarget); try { await command("manage_account", { p_user: selected.id, p_state: String(d.get("state")) }); setSelected(null); } catch { /* Contenedor. */ } }}><label>{t("Nuevo estado", "New state")}<select name="state" defaultValue={str(selected, "state")}><option value="active">{t("Activa", "Active")}</option><option value="suspended">{t("Suspendida", "Suspended")}</option><option value="archived">{t("Archivada", "Archived")}</option></select></label><Message>{t("Suspender revoca el acceso a nuevas operaciones y conserva el historial. Archivar es una baja reversible.", "Suspension revokes access to new operations and preserves history. Archiving is reversible.")}</Message><button disabled={busy} className="button button-primary">{t("Guardar estado", "Save state")}</button></form><form onSubmit={async e => { e.preventDefault(); const d = new FormData(e.currentTarget); try { await command("set_role", { p_user: selected.id, p_role: String(d.get("role")), p_enabled: d.get("enabled") === "yes" }); } catch { /* Contenedor. */ } }}><label>{t("Rol a modificar", "Role to change")}<select name="role">{(Object.keys(roleNames) as Role[]).map(role => <option key={role} value={role}>{roleNames[role][lang]}</option>)}</select></label><label className="checkbox-label"><input name="enabled" value="yes" type="checkbox" defaultChecked />{t("Habilitar este rol", "Enable this role")}</label><button className="button button-secondary" disabled={busy}>{t("Aplicar rol", "Apply role")}</button></form><form onSubmit={async e => { e.preventDefault(); const d = new FormData(e.currentTarget); try { await command("set_permission", { p_user: selected.id, p_permission: String(d.get("permission")), p_enabled: d.get("enabled") === "yes" }); } catch { /* Contenedor. */ } }}><label>{t("Permiso académico específico", "Specific academic permission")}<select name="permission">{[["structure.manage", t("Estructura académica", "Academic structure")], ["enrollment.manage", t("Matrículas y asignaciones", "Enrollment and assignments")], ["evaluation.manage", t("Esquemas de evaluación", "Assessment schemes")], ["period.close", t("Cierre de períodos", "Term closing")], ["identity.manage", t("Correcciones de identidad", "Identity corrections")], ["contact.manage", t("Consultas de contacto", "Contact requests")]].map(([permission, label]) => <option key={permission} value={permission}>{label}</option>)}</select></label><label className="checkbox-label"><input name="enabled" value="yes" type="checkbox" defaultChecked />{t("Habilitar permiso", "Enable permission")}</label><button className="button button-secondary" disabled={busy}>{t("Aplicar permiso", "Apply permission")}</button></form></> : <Empty title={t("Selecciona un usuario", "Select an account")} description={t("Podrás suspender, reactivar o archivar su cuenta.", "You can suspend, reactivate or archive their account.")} />}</section></div></>;
}

function AcademicPanel({ data, command, busy, text, can }: { data: Dataset; command: Command; busy: boolean; text: (row: Row | undefined, field: string) => string; can: (permission: string) => boolean }) {
  const { t } = useUI(); const [kind, setKind] = useState(can("structure.manage") ? "program" : "enrollment"); const [weights, setWeights] = useState([{ name: "Tareas", weight: 50 }, { name: "Proyecto", weight: 50 }]); const [error, setError] = useState("");
  const options = (resource: string, name = "name") => (data[resource] ?? []).map(row => <option key={row.id} value={row.id}>{text(row, name)}</option>);
  const run: Command = async (op, params) => { try { return await command(op, params); } catch { return undefined; } };
  return <><div className="overview-stats">{[["programs", t("Carreras", "Programs")], ["subjects", t("Materias", "Courses")], ["groups", t("Grupos", "Groups")], ["periods", t("Períodos", "Terms")]].map(([resource, name]) => <div key={resource}><strong>{(data[resource] ?? []).length}</strong><span>{name}</span></div>)}</div><div className="portal-columns">{(can("structure.manage") || can("enrollment.manage")) && <section className="detail-panel"><h2>{t("Estructura y matrículas", "Structure and enrollment")}</h2><form onSubmit={async e => { e.preventDefault(); const d = new FormData(e.currentTarget); const p: Record<string, unknown> = {}; d.forEach((value, key) => { if (value) p[key] = String(value); }); await run("manage_structure", { p_kind: kind, p_data: p }); }}><label>{t("Qué quieres crear", "What would you like to create")}<select value={kind} onChange={e => setKind(e.target.value)}>{[["program", t("Carrera", "Program")], ["period", t("Período", "Term")], ["subject", t("Materia", "Course")], ["group", t("Grupo", "Group")], ["enrollment", t("Matrícula de estudiante", "Student enrollment")], ["teacher_assignment", t("Asignación docente", "Teacher assignment")]].filter(([value]) => can(["enrollment", "teacher_assignment"].includes(value) ? "enrollment.manage" : "structure.manage")).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>{!["enrollment", "teacher_assignment"].includes(kind) && <label>{t("Nombre", "Name")}<input name="name" required maxLength={200} /></label>}{kind === "period" && <div className="form-two"><label>{t("Inicio", "Starts")}<input type="date" name="starts_on" required /></label><label>{t("Finalización", "Ends")}<input type="date" name="ends_on" required /></label></div>}{kind === "subject" && <label>{t("Carrera", "Program")}<select name="program_id" required>{options("programs")}</select></label>}{kind === "group" && <><label>{t("Materia", "Course")}<select name="subject_id" required>{options("subjects")}</select></label><label>{t("Período", "Term")}<select name="period_id" required>{options("periods")}</select></label></>}{["enrollment", "teacher_assignment"].includes(kind) && <><label>{t("Persona", "Person")}<select name="user_id" required>{options("profiles", "full_name")}</select></label><label>{t("Grupo", "Group")}<select name="group_id" required>{options("groups")}</select></label></>}<button className="button button-primary" disabled={busy}>{t("Guardar", "Save")}<Icon name="check" size={17} /></button></form>{can("structure.manage") && <><h3>{t("Editar o archivar", "Edit or archive")}</h3><form onSubmit={async e => { e.preventDefault(); const d = new FormData(e.currentTarget); await run("edit_structure", { p_kind: "group", p_id: String(d.get("id")), p_data: { name: String(d.get("name")) } }); }}><label>{t("Grupo", "Group")}<select name="id">{options("groups")}</select></label><label>{t("Nuevo nombre", "New name")}<input name="name" required maxLength={200} /></label><button className="button button-secondary" disabled={busy}>{t("Actualizar grupo", "Update group")}</button></form></>}</section>}{(can("evaluation.manage") || can("period.close")) && <section className="detail-panel">{can("evaluation.manage") && <><h2>{t("Esquema de evaluación", "Assessment scheme")}</h2><p>{t("Define las categorías por materia y período. Los porcentajes deben sumar 100 %. Los valores iniciales son un ejemplo editable.", "Define categories by course and term. Weights must total 100%. Initial values are editable examples.")}</p><form onSubmit={async e => { e.preventDefault(); const d = new FormData(e.currentTarget); setError(""); if (Math.abs(weights.reduce((sum, w) => sum + w.weight, 0) - 100) > .0001) { setError(t("Los porcentajes deben sumar exactamente 100 %.", "Weights must total exactly 100%.")); return; } await run("set_evaluation", { p_subject: String(d.get("subject")), p_period: String(d.get("period")), p_categories: weights }); }}><label>{t("Materia", "Course")}<select name="subject" required>{options("subjects")}</select></label><label>{t("Período", "Term")}<select name="period" required>{options("periods")}</select></label>{weights.map((weight, i) => <div key={i} className="form-two"><label>{t("Categoría", "Category")}<input value={weight.name} maxLength={100} required onChange={e => setWeights(weights.map((w, j) => j === i ? { ...w, name: e.target.value } : w))} /></label><label>{t("Porcentaje", "Weight")}<input type="number" min={.01} max={100} step=".01" required value={weight.weight} onChange={e => setWeights(weights.map((w, j) => j === i ? { ...w, weight: Number(e.target.value) } : w))} /></label></div>)}<div className="inline-actions"><button type="button" className="small-link" onClick={() => setWeights([...weights, { name: "", weight: 0 }])}>{t("Añadir categoría", "Add category")}</button>{weights.length > 1 && <button type="button" className="small-link" onClick={() => setWeights(weights.slice(0, -1))}>{t("Quitar última categoría", "Remove last category")}</button>}</div><strong>{t("Total", "Total")}: {weights.reduce((sum, w) => sum + w.weight, 0).toFixed(2)} %</strong>{error && <Message error>{error}</Message>}<button disabled={busy} className="button button-primary">{t("Guardar evaluación", "Save assessment scheme")}</button></form></>}{can("period.close") && <><h3>{t("Cierre de período", "Close term")}</h3><p>{t("Las no entregadas recibirán 0.0. Cualquier entrega pendiente de revisión bloquea el cierre.", "Missing submissions receive 0.0. Any submission awaiting review blocks closing.")}</p><form onSubmit={async e => { e.preventDefault(); const d = new FormData(e.currentTarget); await run("close_period", { p_period: String(d.get("period")) }); }}><label>{t("Período", "Term")}<select name="period">{options("periods")}</select></label><label className="checkbox-label"><input type="checkbox" required />{t("He revisado las actividades y comprendo el cierre.", "I have reviewed activities and understand closing.")}</label><button disabled={busy} className="button button-secondary">{t("Cerrar período", "Close term")}</button></form></>}</section>}</div>{can("identity.manage") && <IdentityRequests data={data} command={command} busy={busy} />}</>;
}

function EventForm({ periods, command, busy }: { periods: Row[]; command: Command; busy: boolean }) { const { t } = useUI(); return <section className="detail-panel form-panel work-section"><h2>{t("Añadir evento", "Add event")}</h2><form onSubmit={async e => { e.preventDefault(); const d = new FormData(e.currentTarget); try { await command("add_calendar_event", { p_period: String(d.get("period")), p_title: String(d.get("title")), p_start: new Date(String(d.get("start"))).toISOString(), p_end: new Date(String(d.get("end"))).toISOString() }); } catch { /* Contenedor. */ } }}><label>{t("Título", "Title")}<input name="title" required maxLength={200} /></label><label>{t("Período", "Term")}<select name="period">{periods.map(p => <option value={p.id} key={p.id}>{str(p, "name")}</option>)}</select></label><div className="form-two"><label>{t("Inicio", "Starts")}<input type="datetime-local" name="start" required /></label><label>{t("Finalización", "Ends")}<input type="datetime-local" name="end" required /></label></div><button disabled={busy} className="button button-primary">{t("Guardar evento", "Save event")}</button></form></section>; }

function AuditPanel({ data, viewerId, command, busy, date }: { data: Dataset; viewerId: string; command: Command; busy: boolean; date: (value: unknown, time?: boolean) => string }) {
  const { t } = useUI(); const run: Command = async (operation, params) => { try { return await command(operation, params); } catch { return undefined; } };
  return <><Message>{t("La baja habitual es archivar. Solo las cuentas sin historial pueden eliminarse definitivamente, con dos administradores distintos y verificación adicional.", "Archiving is the usual removal method. Only accounts without history may be permanently deleted, with two distinct administrators and additional verification.")}</Message><section className="detail-panel form-panel work-section"><h2>{t("Solicitar eliminación excepcional", "Request exceptional deletion")}</h2><form onSubmit={async e => { e.preventDefault(); const d = new FormData(e.currentTarget); await run("request_deletion", { p_user: String(d.get("user")) }); }}><label>{t("Cuenta sin historial", "Account without history")}<select name="user" required>{(data.profiles ?? []).filter(p => p.id !== viewerId).map(p => <option value={p.id} key={p.id}>{str(p, "full_name")}</option>)}</select></label><button className="button button-secondary" disabled={busy}>{t("Solicitar revisión de baja", "Request removal review")}</button></form></section><section className="work-section"><h2>{t("Solicitudes de eliminación", "Deletion requests")}</h2>{(data.deletion_requests ?? []).map(request => <div className="detail-panel work-section" key={request.id}><h3>{str(request, "status", str(request, "state"))}</h3><p>{t("Cuenta", "Account")}: {str(request, "target_id", str(request, "user_id"))}</p><div className="inline-actions"><button disabled={busy} className="button button-secondary" onClick={() => void run("approve_deletion", { p_request: request.id })}>{t("Aprobar como segundo administrador", "Approve as second administrator")}</button><button disabled={busy} className="button button-secondary" onClick={() => void run("cancel_deletion", { p_request: request.id })}>{t("Cancelar solicitud", "Cancel request")}</button></div><form onSubmit={async e => { e.preventDefault(); const d = new FormData(e.currentTarget); if (d.get("confirm") === "ELIMINAR") await run("execute_deletion", { id: request.id }); }}><label>{t("Escribe ELIMINAR para solicitar la ejecución autorizada", "Type ELIMINAR to request authorized execution")}<input name="confirm" pattern="ELIMINAR" required autoComplete="off" /></label><button className="button button-danger" disabled={busy}>{t("Ejecutar eliminación autorizada", "Execute authorized deletion")}</button></form></div>)}{!(data.deletion_requests ?? []).length && <Empty title={t("Sin solicitudes", "No requests")} description={t("No hay eliminaciones pendientes.", "No pending deletions.")} />}</section><section className="work-section"><h2>{t("Registro de actividad", "Activity log")}</h2><Table headings={[t("Acción", "Action"), t("Recurso", "Resource"), t("Fecha", "Date")]} empty={t("No hay actividad para mostrar.", "No activity to display.")}>{(data.audit_events ?? []).map(event => <tr key={event.id}><td>{str(event, "action")}</td><td>{str(event, "entity")}</td><td>{date(event.created_at, true)}</td></tr>)}</Table></section></>;
}

function simulate(current: Dataset, operation: string, p: Record<string, unknown>, viewer: string): Dataset {
  const next: Dataset = Object.fromEntries(Object.entries(current).map(([key, values]) => [key, values.map(value => ({ ...value }))])); const list = (name: string) => next[name] ?? (next[name] = []); const id = () => crypto.randomUUID(); const now = new Date().toISOString();
  const audit = () => list("audit_events").unshift({ id: id(), action: operation, entity: "preview", resource_id: String(p.p_user ?? p.p_submission ?? ""), created_at: now });
  switch (operation) {
    case "submit_work": { const s = list("submissions").find(s => s.id === p.p_submission); if (!s || (number(s, "current_version") > 0 && !s.replacement_allowed)) throw new Error("El reemplazo requiere autorización del docente."); const task = list("tasks").find(t => t.id === s.task_id)!; if (list("periods").some(term => term.closed_at && list("groups").some(g => g.id === task.group_id && g.period_id === term.id))) throw new Error("El período está cerrado."); s.current_version = number(s, "current_version") + 1; s.replacement_allowed = false; s.grade = null; list("submission_versions").push({ id: id(), submission_id: s.id, version: s.current_version, body: String(p.p_body), upload_ids: p.p_uploads, submitted_at: now, late: Date.parse(str(task, "due_at")) < Date.now() }); break; }
    case "review_work": { const s = list("submissions").find(s => s.id === p.p_submission); if (!s) throw new Error("Entrega no disponible"); if (p.p_action === "authorize_replacement") s.replacement_allowed = true; else { const grade = Number(p.p_grade); if (!Number.isFinite(grade) || grade < 0 || grade > 5 || number(s, "current_version") === 0) throw new Error("La nota debe estar entre 0.0 y 5.0 para una entrega confirmada."); list("grade_history").push({ id: id(), submission_id: s.id, old_grade: s.grade, new_grade: grade, actor_id: viewer, reason: String(p.p_comment || "Calificación docente"), created_at: now }); s.grade = grade; s.graded_at = now; list("notifications").push({ id: id(), user_id: s.student_id, kind: "grade", resource_id: s.id, read_at: null, created_at: now, title: "Tienes una nueva calificación", title_en: "You have a new grade" }); if (p.p_comment) list("comments").push({ id: id(), submission_id: s.id, author_id: viewer, body: String(p.p_comment), created_at: now }); } break; }
    case "add_comment": list("comments").push({ id: id(), submission_id: String(p.p_submission), author_id: viewer, body: String(p.p_body), created_at: now }); break;
    case "mark_notification": { const notification = list("notifications").find(n => n.id === p.p_notification); if (notification) notification.read_at = now; break; }
    case "mark_all_notifications": list("notifications").forEach(n => { n.read_at = now; }); break;
    case "update_my_profile": { const profile = list("profiles").find(r => r.id === viewer); if (profile) { profile.address = String(p.p_address); profile.avatar_path = p.p_avatar_path; } break; }
    case "manage_account": { const profile = list("profiles").find(r => r.id === p.p_user); if (profile) profile.state = String(p.p_state); break; }
    case "set_role": { const profile = list("profiles").find(r => r.id === p.p_user); if (profile) profile.role = p.p_enabled ? p.p_role : ""; break; }
    case "set_permission": { const profile = list("profiles").find(r => r.id === p.p_user); if (profile) { const permissions = Array.isArray(profile.permissions) ? profile.permissions as string[] : []; profile.permissions = p.p_enabled ? [...new Set([...permissions, String(p.p_permission)])] : permissions.filter(value => value !== p.p_permission); } break; }
    case "set_rubric": { const old = list("rubrics").find(r => r.task_id === p.p_task); if (old) old.criteria = p.p_criteria; else list("rubrics").push({ id: id(), task_id: p.p_task, criteria: p.p_criteria }); break; }
    case "mark_contact": { const contact = list("contact_inquiries").find(r => r.id === p.p_contact); if (contact) contact.status = "reviewed"; break; }
    case "retire_structure": { const map: Record<string,string> = { program: "programs", subject: "subjects", group: "groups", period: "periods" }; const target = list(map[String(p.p_kind)]).find(r => r.id === p.p_id); if (target) target.archived_at = now; break; }
    case "remove_assignment": { const kind = p.p_kind === "enrollment" ? "enrollments" : "teacher_groups"; next[kind] = list(kind).filter(r => r.group_id !== p.p_group || (r.student_id ?? r.teacher_id) !== p.p_user); break; }
    case "correct_identity": { const profile = list("profiles").find(r => r.id === p.p_user); if (profile) { profile.full_name = p.p_name; profile.document_number = p.p_document; profile.birth_date = p.p_birth; } break; }
    case "assign_program": { const profile = list("profiles").find(r => r.id === p.p_user); if (profile) profile.program_id = p.p_program; break; }
    case "set_translation": { const kinds: Record<string, string> = { task: "tasks", comment: "comments", program: "programs", subject: "subjects", category: "categories" }; const record = list(kinds[String(p.p_kind)]).find(r => r.id === p.p_id); if (!record) throw new Error("Original no disponible."); const fields = p.p_fields as Record<string, string>; Object.entries(fields).forEach(([key, value]) => { record[`${key}_${p.p_locale === "es" ? "es" : "en"}`] = value; }); break; }
    case "invite": list("profiles").push({ id: id(), full_name: String(p.full_name), email: String(p.email), state: "active", role: p.role }); break;
    case "publish_task": { const groups = p.p_groups as string[]; const students = p.p_students as string[] | null; groups.forEach(g => { const group = list("groups").find(item => item.id === g)!; const category = list("categories").find(c => c.subject_id === group.subject_id && c.name === p.p_category_name); if (!category) throw new Error("El grupo no tiene esa categoría de evaluación."); const tid = id(); list("tasks").push({ id: tid, group_id: g, category_id: category.id, title: p.p_title, description: p.p_description, due_at: p.p_due_at, author_id: viewer }); list("enrollments").filter(e => e.group_id === g && (!students || students.includes(String(e.student_id)))).forEach(e => list("submissions").push({ id: id(), task_id: tid, student_id: e.student_id, current_version: 0, replacement_allowed: false, grade: null })); }); break; }
    case "manage_structure": { const value = { ...(p.p_data as Record<string, unknown>) }; if (p.p_kind === "enrollment") value.student_id = value.user_id; if (p.p_kind === "teacher_assignment") value.teacher_id = value.user_id; const map: Record<string, string> = { program: "programs", period: "periods", subject: "subjects", group: "groups", enrollment: "enrollments", teacher_assignment: "teacher_groups" }; list(map[String(p.p_kind)]).push({ id: id(), ...value, ...(p.p_kind === "period" ? { closed_at: null } : {}) }); break; }
    case "edit_structure": { const map: Record<string,string> = { program: "programs", subject: "subjects", group: "groups", period: "periods" }; const target = list(map[String(p.p_kind)]).find(r => r.id === p.p_id); if (target) Object.assign(target, p.p_data); break; }
    case "set_evaluation": { const old = list("categories").filter(c => c.subject_id === p.p_subject && c.period_id === p.p_period); const incoming = p.p_categories as { name: string; weight: number }[]; if (old.some(c => !incoming.some(n => n.name === c.name) && list("tasks").some(task => task.category_id === c.id))) throw new Error("No puedes quitar una categoría con actividades."); next.categories = list("categories").filter(c => c.subject_id !== p.p_subject || c.period_id !== p.p_period); incoming.forEach(c => list("categories").push({ id: old.find(category => category.name === c.name)?.id ?? id(), subject_id: p.p_subject, period_id: p.p_period, ...c })); break; }
    case "close_period": throw new Error("La vista previa no cierra períodos institucionales. En el acceso real, las entregas pendientes de revisión bloquean el cierre.");
    case "request_identity_change": list("identity_requests").push({ id: id(), user_id: viewer, proposed: p.p_proposed, reason: p.p_reason, state: "pending" }); break;
    case "resolve_identity_request": { const request = list("identity_requests").find(r => r.id === p.p_request); if (!request || (request.status ?? request.state) !== "pending") throw new Error("Solicitud no disponible."); if (p.p_accept) { const profile = list("profiles").find(r => r.id === request.user_id); if (profile) Object.assign(profile, request.proposed); } request.status = p.p_accept ? "resolved" : "rejected"; request.state = request.status; break; }
    case "add_calendar_event": list("calendar_events").push({ id: id(), title: p.p_title, period_id: p.p_period, starts_at: p.p_start, ends_at: p.p_end }); break;
    case "request_deletion": { const target = list("submissions").some(s => s.student_id === p.p_user) || list("enrollments").some(e => e.student_id === p.p_user); if (target) throw new Error("Una cuenta con historial debe archivarse."); list("deletion_requests").push({ id: id(), user_id: p.p_user, requested_by: viewer, status: "pending" }); break; }
    case "approve_deletion": { const request = list("deletion_requests").find(r => r.id === p.p_request); if (request?.requested_by === viewer) throw new Error("La aprobación requiere otro administrador."); if (request) { request.status = "approved"; request.approved_by = viewer; } break; }
    case "cancel_deletion": { const request = list("deletion_requests").find(r => r.id === p.p_request); if (request) request.status = "canceled"; break; }
    case "execute_deletion": throw new Error("La eliminación definitiva está deshabilitada en la vista previa.");
    default: throw new Error("Operación no disponible en la vista previa.");
  }
  audit(); return next;
}
